    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);
        require(withdrawAmount <= depositAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && address(c).balance == balanceBefore - withdrawAmount);
    }

    receive() external payable {}
