// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depositAmount, uint256 withdrawAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(withdrawAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == balanceBefore - withdrawAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 withdrawAmount) public {
        _run(depositAmount, withdrawAmount);
    }

    receive() external payable {}
}
